  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Charts & Boxes */
.empty-box {
  height: 160px;
  background: #fafbfc;
  border: 1px dashed var(--border-color);
  border-radius: 6px;
  display: flex;
  align-items: center;
