  padding: 6px 12px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-main);
  align-self: flex-start;
  transition: background 0.2s;
}

.btn-browse:hover {
  background: var(--bg-color);
}

.btn-connector.active {
  border-style: solid;
  border-color: var(--success-green);
  background: #e3fcef;
}

.btn-connector.active .conn-text span {
  color: var(--success-green);
