.pipe-node h4 { margin: 0 0 8px 0; color: var(--text-main); font-size: 14px; }
.pipe-metric { font-size: 12px; color: var(--text-muted); }
.pipe-arrow { font-size: 24px; color: var(--border-color); padding: 0 20px; }
.pipe-node.active-node { border: 2px solid var(--vibrant-purple); background: #f5f3ff; box-shadow: 0 4px 10px rgba(101, 84, 192, 0.1); }

/* Tables */
