                    "css": ":root {
  --bg-color: #f7f9fa;
  --card-bg: #ffffff;
  --text-main: #2A2A2A;
  --text-muted: #5e6c84;
  --border-color: #dfe1e6;
  --alert-red: #de350b;
  --accent-blue: #0052cc;
  --success-green: #00875a;
  --warning-orange: #ff991f;
  --vibrant-purple: #6554c0;
  --vibrant-cyan: #00b8d9;
  --radius: 8px;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-color);
  padding: 24px;
  color: var(--text-main);
  margin: 0;
}

.genw-dashboard {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.row {
  display: grid;
  gap: 24px;
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

h3 {
  margin: 0 0 20px 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

/* KPIs */
.kpi {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  border-top: 4px solid var(--accent-blue);
}

.kpi.success {
  border-top-color: var(--success-green);
}

.kpi.warning {
  border-top-color: var(--warning-orange);
}

.kpi.alert {
  border-top-color: var(--alert-red);
}

.kpi p {
  font-size: 36px;
  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Vendor List */
.vendor-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.vendor-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  background: #fafbfc;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: transform 0.2s;
}

.vendor-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
  border-color: var(--vibrant-purple);
}

.vendor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.vendor-info h4 {
  margin: 0;
  font-size: 16px;
  color: var(--text-main);
}

.vendor-info span {
  font-size: 12px;
  color: var(--text-muted);
}

/* Pipeline Flow */
.flow-pipeline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #fff;
  padding: 12px;
  border-radius: 6px;
  border: 1px solid #ebecf0;
}

.flow-step {
  flex: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.step-icon {
  font-size: 18px;
}

.step-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}

.step-status {
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 10px;
  display: inline-block;
  margin: 0 auto;
}

.arrow {
  color: var(--border-color);
  font-weight: bold;
}

/* Status Colors */
.pass {
  background: #e3fcef;
  color: var(--success-green);
}

.fail {
  background: #ffebe6;
  color: var(--alert-red);
}

.warn {
  background: #fff0b3;
  color: var(--warning-orange);
}

.wait {
  background: #deebff;
  color: var(--accent-blue);
}

.final-score {
  font-size: 14px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 4px;
  color: #fff;
}

.score-good {
  background: var(--success-green);
}

.score-bad {
  background: var(--alert-red);
}

.score-med {
  background: var(--warning-orange);
}

/* Button */
.load-more-box {
  text-align: center;
  margin-top: 24px;
}

.btn-vibrant {
  background: linear-gradient(135deg, var(--vibrant-purple) 0%, var(--accent-blue) 100%);
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: 24px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
  box-shadow: 0 4px 10px rgba(101, 84, 192, 0.3);
}

.btn-vibrant:hover {
  opacity: 0.9;
}",
                    "js": "let allVendors = [];
let visibleCount = 5;
let kpiData = {};
appsmith.onReady(() => {
  let rawData = appsmith.model;
  let vendors = [];
  if (rawData && Array.isArray(rawData)) vendors = rawData;else if (rawData && rawData.vendors) vendors = rawData.vendors;
  if (!vendors || vendors.length === 0) {
    document.body.innerHTML = '<div style="padding: 20px; font-family: sans-serif; color: #666;">Waiting for database records...</div>';
    return;
  }

  // --- DATA LOGIC FROM JS #1 (unchanged) ---
  let screened = vendors.length;
  let verified = 0,
    pending = 0,
    risk = 0;
  allVendors = vendors.map(v => {
    let score = "Pending";
    let scoreClass = "score-med";
    const rating = (v.risk_rating || '').toLowerCase();
    if (rating === 'low') {
      score = "98/100";
      scoreClass = "score-good";
      if (!v.blacklist_status) verified++;
    } else if (rating === 'medium') {
      score = "65/100";
      scoreClass = "score-med";
      pending++;
    } else if (rating === 'high') {
      score = "21/100";
      scoreClass = "score-bad";
      risk++;
    } else {
      pending++;
    }
    if (v.blacklist_status) risk++;
    const gstinStatus = v.official_gstin ? "Active" : "Mismatch";
    const gstinClass = v.official_gstin ? "pass" : "warn";
    const watchlistStatus = v.blacklist_status ? "Flagged" : "Clear";
    const watchlistClass = v.blacklist_status ? "fail" : "pass";
    return {
      id: v.vendor_id,
      name: v.vendor_name || "Unknown Vendor",
      score,
      scoreClass,
      flow: [{
        name: "KYC Check",
        icon: "🏢",
        status: "Verified",
        statClass: "pass"
      }, {
        name: "GSTIN Valid",
        icon: "📑",
        status: gstinStatus,
        statClass: gstinClass
      }, {
        name: "Bank Match",
        icon: "🏦",
        status: "Matched",
        statClass: "pass"
      }, {
        name: "Watchlist",
        icon: "🔍",
        status: watchlistStatus,
        statClass: watchlistClass
      }]
    };
  });
  kpiData = {
    screened: screened.toLocaleString(),
    verified: verified.toLocaleString(),
    pending: pending.toLocaleString(),
    risk: risk.toLocaleString()
  };

  // --- POPULATE KPIs (JS #2 style — elements already exist in HTML tab) ---
  document.getElementById('kpi-screened').textContent = kpiData.screened;
  document.getElementById('kpi-verified').textContent = kpiData.verified;
  document.getElementById('kpi-pending').textContent = kpiData.pending;
  document.getElementById('kpi-risk').textContent = kpiData.risk;

  // --- RENDER PIPELINE (JS #2 style) ---
  const container = document.getElementById('vendor-container');
  const renderVendors = () => {
    const visibleVendors = allVendors.slice(0, visibleCount);
    container.innerHTML = ''; // clear before re-render to avoid duplicates

    visibleVendors.forEach(v => {
      let stepsHTML = v.flow.map((step, index) => `
                <div class="flow-step">
                    <span class="step-icon">${step.icon}</span>
                    <span class="step-label">${step.name}</span>
                    <span class="step-status ${step.statClass}">${step.status}</span>
                </div>
                ${index < 3 ? '<div class="arrow">➔</div>' : ''}
            `).join('');
      container.innerHTML += `
                <div class="vendor-card">
                    <div class="vendor-header">
                        <div class="vendor-info">
                            <h4>${v.name}</h4>
                            <span>Vendor ID: ${v.id}</span>
                        </div>
                        <div class="final-score ${v.scoreClass}">Risk Score: ${v.score}</div>
                    </div>
                    <div class="flow-pipeline">
                        ${stepsHTML}
                    </div>
                </div>
            `;
    });
  };
  renderVendors();

  // --- LOAD MORE (JS #2 style) ---
  document.getElementById('btn-load-more').addEventListener('click', function () {
    this.textContent = "Loading...";
    setTimeout(() => {
      visibleCount += 5;
      renderVendors();
      if (visibleCount >= allVendors.length) {
        this.textContent = "No More Records";
        this.disabled = true;
        this.style.opacity = "0.5";
      } else {
        this.textContent = "Load More Records ↻";
      }
    }, 800);
  });
});"
