  "query": "WITH kpis AS (SELECT COUNT(i.invoice_id) as checked, COUNT(CASE WHEN ar.risk_rating IN ('MEDIUM', 'HIGH', 'CRITICAL') THEN 1 END) as discrepancies FROM invoices i LEFT JOIN audit_results ar ON i.invoice_id = ar.invoice_id), matches AS (SELECT jsonb_agg(jsonb_build_object('id', i.invoice_id, 'po', i.po_id, 'vendor', v.vendor_name, 'status', CASE WHEN i.invoice_amount = po.po_amount AND i.invoice_amount = gr.received_amount THEN 'Match' ELSE 'Mismatch' END)) as results_data FROM (SELECT i.* FROM invoices i ORDER BY i.date DESC LIMIT 10) i LEFT JOIN vendor_master v ON i.vendor_id = v.vendor_id LEFT JOIN purchase_orders po ON i.po_id = po.po_id LEFT JOIN goods_receipts gr ON i.grn_id = gr.grn_id), extracted_flags AS (SELECT COALESCE(f->>'type', f->>'Flag Type', 'General Discrepancy') as theme_name, ar.risk_rating FROM audit_results ar, LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(ar.flags_detected) = 'array' THEN ar.flags_detected ELSE '[]'::jsonb END) f), themes AS (SELECT jsonb_agg(jsonb_build_object('theme', t.theme_name, 'count', t.occurrences, 'risk', t.risk_score || '/100')) as themes_data FROM (SELECT theme_name, COUNT(*) as occurrences, CASE WHEN MAX(risk_rating) = 'CRITICAL' THEN 98 WHEN MAX(risk_rating) = 'HIGH' THEN 85 WHEN MAX(risk_rating) = 'MEDIUM' THEN 62 ELSE 24 END as risk_score FROM extracted_flags WHERE theme_name IS NOT NULL GROUP BY theme_name ORDER BY COUNT(*) DESC LIMIT 4) t) SELECT jsonb_build_object('kpis', (SELECT jsonb_build_object('checked', checked, 'discrepancies', discrepancies, 'matched', checked - discrepancies, 'confidence', COALESCE(ROUND(((checked - discrepancies)::numeric / NULLIF(checked, 0)) * 100, 1)::text, '0') || '%') FROM kpis), 'results', COALESCE((SELECT results_data FROM matches), '[]'::jsonb), 'themes', COALESCE((SELECT themes_data FROM themes), '[]'::jsonb)) AS dashboard_data;",
