});

async function run() {
  const client = new Client({ connectionString });
  try {
    await client.connect();
    console.log("Connected to Neon DB. Preparing to insert mock data...");

    // Optional: Clean up older test records
    await client.query("DELETE FROM vendor_audits WHERE vendorid LIKE 'TESTVEND%';");

    for (const record of mockData) {
      const keys = Object.keys(record);
      const values = Object.values(record);

      const query = `
        INSERT INTO vendor_audits (${keys.join(', ')})
        VALUES (${keys.map((_, i) => `$${i + 1}`).join(', ')})
      `;
      await client.query(query, values);
    }
    console.log("Successfully inserted 20 mock records.");
  } catch (err) {
    console.error("Error inserting data:", err);
  } finally {
    await client.end();
  }
}
run();

{
  "name": "risk_scoring_calculator",
  "description": "Always use this tool at the very end of your audit. Count the number of critical, high, and medium flags you found, and pass them to this tool to calculate the final Risk Score and get the routing recommendation.",
  "color": "linear-gradient(rgb(22,169,217), rgb(74,242,180))",
  "iconSrc": "",
  "schema": "[{"id":1,"property":"critical_flags","type":"number","description":"Count of critical risks found (e.g., Blacklisted vendor, Exa news of fraud, Duplicate invoice)","required":true},{"id":2,"property":"high_flags","type":"number","description":"Count of high risks found (e.g., Three-way match failure, GST mismatch, Approval limit violation)","required":true},{"id":3,"property":"medium_flags","type":"number","description":"Count of medium/fuzzy risks found (e.g., Round number anomalies, weekend timing)","required":true}]",
  "func": "// Calculate weighted score
let score = ($critical_flags * 50) + ($high_flags * 25) + ($medium_flags * 10);

// Cap the score at 100
if (score > 100) score = 100;

let routing_decision = "";

// The Conditional Escalation Logic
if (score >= 75) {
    routing_decision = "ACTION: ESCALATE TO HITL (Human-in-the-Loop) REVIEW QUEUE. Transaction is blocked.";
} else if (score >= 40) {
    routing_decision = "ACTION: ROUTE TO QA SAMPLING. High risk detected.";
} else if (score > 0) {
    routing_decision = "ACTION: AUTO-CLASSIFY EXCEPTION. Medium risk detected.";
} else {
    routing_decision = "ACTION: AUTO-APPROVE. No risks detected.";
}

return `CALCULATED RISK SCORE: ${score}/100. ${routing_decision}`;",
  "workspaceId": "16accf17-ab67-4be2-b196-8f0db2b94aae"
}

