              "variableName": "flags_2b",
              "variableValue": "<p><span class=\"variable\" data-type=\"mention\" data-id=\"$flow.state.flags2B\" data-label=\"$flow.state.flags2B\">{{ $flow.state.flags2B }}</span> </p>"
            },
