.btn-primary { background: linear-gradient(135deg, var(--vibrant-purple) 0%, var(--accent-blue) 100%); color: white; border: none; padding: 10px 20px; border-radius: 4px; font-weight: 600; cursor: pointer; transition: opacity 0.2s; box-shadow: 0 2px 4px rgba(101, 84, 192, 0.2); }
.btn-primary:hover { opacity: 0.9; }
.btn-outline { background: transparent; color: var(--text-main); border: 1px solid var(--border-color); padding: 10px 20px; border-radius: 4px; font-weight: 600; cursor: pointer; transition: background 0.2s; }
.btn-outline:hover { background: #ebecf0; }

/* Cards & KPIs */
.card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); }
h3 { margin: 0 0 16px 0; font-size: 13px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.8px; }

.kpi { display: flex; flex-direction: column; justify-content: center; text-align: center; border-top: 4px solid var(--accent-blue); }
.kpi.warning { border-top-color: var(--warning-orange); }
.kpi.alert { border-top-color: var(--alert-red); }
.kpi p { font-size: 32px; font-weight: 800; margin: 0; color: var(--text-main); }

/* Table Styling */
table { width: 100%; border-collapse: collapse; font-size: 13px; }
