                    "css": ":root {
  --bg-color: #f7f9fa;
  --card-bg: #ffffff;
  --text-main: #2A2A2A;
  --text-muted: #5e6c84;
  --border-color: #dfe1e6;
  --alert-red: #de350b;
  --accent-blue: #0052cc;
  --success-green: #00875a;
  --warning-orange: #ff991f;
  --vibrant-purple: #6554c0;
  --vibrant-cyan: #00b8d9;
  --radius: 8px;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-color);
  padding: 24px;
  color: var(--text-main);
  margin: 0;
}

.genw-dashboard {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.row {
  display: grid;
  gap: 24px;
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

h3 {
  margin: 0 0 20px 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

/* KPIs */
.kpi {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  border-top: 4px solid var(--accent-blue);
}

.kpi.success {
  border-top-color: var(--success-green);
}

.kpi.warning {
  border-top-color: var(--warning-orange);
}

.kpi.alert {
  border-top-color: var(--alert-red);
}

.kpi p {
  font-size: 36px;
  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Vendor List */
.vendor-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.vendor-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  background: #fafbfc;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: transform 0.2s;
}

.vendor-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
  border-color: var(--vibrant-purple);
}

.vendor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.vendor-info h4 {
  margin: 0;
  font-size: 16px;
  color: var(--text-main);
}

.vendor-info span {
  font-size: 12px;
  color: var(--text-muted);
}

/* Pipeline Flow */
.flow-pipeline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #fff;
  padding: 12px;
  border-radius: 6px;
  border: 1px solid #ebecf0;
}

.flow-step {
  flex: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.step-icon {
  font-size: 18px;
}

.step-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}

.step-status {
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 10px;
  display: inline-block;
  margin: 0 auto;
}

.arrow {
  color: var(--border-color);
  font-weight: bold;
}

/* Status Colors */
.pass {
  background: #e3fcef;
  color: var(--success-green);
}

.fail {
  background: #ffebe6;
  color: var(--alert-red);
}

.warn {
  background: #fff0b3;
  color: var(--warning-orange);
}

.wait {
  background: #deebff;
  color: var(--accent-blue);
}

.final-score {
  font-size: 14px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 4px;
  color: #fff;
}

.score-good {
  background: var(--success-green);
}

.score-bad {
  background: var(--alert-red);
}

.score-med {
  background: var(--warning-orange);
}

/* Button */
.load-more-box {
  text-align: center;
  margin-top: 24px;
}

.btn-vibrant {
  background: linear-gradient(135deg, var(--vibrant-purple) 0%, var(--accent-blue) 100%);
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: 24px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
  box-shadow: 0 4px 10px rgba(101, 84, 192, 0.3);
}

.btn-vibrant:hover {
  opacity: 0.9;
}",
