            body: JSON.stringify(payload)
          });

          if (!response.ok) throw new Error(`API ${response.status} ${response.statusText}`);

          const rawData = await response.json();
          const parsed = parseAgentResponse(rawData);

          // Write ALL fields back to audit_results
          await client.query(`
            UPDATE audit_results
            SET risk_rating             = $1,
                flags_detected          = $2::jsonb,
                policy_version_applied  = $3,
                session_id              = $4,
                explanation             = $5,
                recommended_action      = $6,
                citation                = $7
            WHERE invoice_id = $8
          `, [
            parsed.riskRating,
            JSON.stringify(parsed.flagsDetected),
            parsed.policyVersion,
            parsed.chatId,
            parsed.explanation,
            parsed.recommendedAction,
            parsed.citation,
            invoiceId
          ]);

          if (parsed.isHITL) {
            hitlCount++;
            console.log(`  [HITL] ${invoiceId} -> paused for human review (session: ${parsed.chatId})`);
          } else {
            successCount++;
            console.log(`  [OK]   ${invoiceId} -> ${parsed.riskRating} | flags: ${parsed.flagsDetected.length} | action: ${parsed.recommendedAction}`);
          }

          return { invoiceId, status: 'dispatched', ...parsed };

        } catch (err) {
          errorCount++;
          console.error(`  [ERR]  ${invoiceId} -> ${err.message}`);
          return { invoiceId, status: 'error', error: err.message };
        }
      });

      await Promise.all(promises);
    }

    console.log(`\n=== MASS AUDIT COMPLETE ===`);
    console.log(`  Completed:    ${successCount}`);
    console.log(`  Pending HITL: ${hitlCount}`);
    console.log(`  Errors:       ${errorCount}`);
    console.log(`  Total:        ${invoiceIds.length}`);

  } catch (err) {
    console.error("Fatal error:", err);
  } finally {
    await client.end();
  }
}

