            }
          ],
          "customFunctionJavascriptFunction": "const https = require('https');\n\n// The SQL query injected from your flow state variables\nconst sqlQuery = typeof $sqlQuery !== 'undefined' ? $sqlQuery : '';\n\n// Your Neon connection string (Highly recommend moving to Key Store eventually!)\nconst connectionString = \"postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require\";\n\nasync function runSQLQuery(query) {\n    return new Promise((resolve) => {\n        if (!query) {\n            return resolve(\"[Error executing query]: No SQL query provided.\");\n        }\n\n        const postData = JSON.stringify({ query: query, params: [] });\n\n        const options = {\n            hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',\n            port: 443,\n            path: '/sql',\n            method: 'POST',\n            headers: {\n                'Content-Type': 'application/json',\n                'Neon-Connection-String': connectionString,\n                'Content-Length': Buffer.byteLength(postData)\n            }\n        };\n\n        const req = https.request(options, (res) => {\n            let data = '';\n            \n            // Accumulate response chunks\n            res.on('data', chunk => data += chunk);\n            \n            res.on('end', () => {\n                if (res.statusCode >= 200 && res.statusCode < 300) {\n                    try {\n                        const parsedData = JSON.parse(data);\n                        // Safely extract rows depending on Neon API response format\n                        const rows = Array.isArray(parsedData) ? parsedData : parsedData.rows || [];\n                        \n                        if (rows.length === 0) {\n                            resolve('[No results returned]');\n                        } else {\n                            // Format results so the LLM can read them cleanly\n                            const columnNames = Object.keys(rows[0]);\n                            const header = columnNames.join(' | ');\n                            \n                            // Map through rows, handle nulls gracefully, and join with pipes\n                            const values = rows.map(row => \n                                columnNames.map(col => row[col] === null ? 'NULL' : String(row[col])).join(' | ')\n                            );\n                            \n                            const formattedResult = query + '\\n' + header + '\\n' + values.join('\\n');\n                            resolve(formattedResult);\n                        }\n                    } catch (e) {\n                        resolve(`[Error parsing response]: ${e.message}`);\n                    }\n                } else {\n                    // This captures SQL syntax errors returned by the Neon DB\n                    resolve(`[Error executing query]: ${data}`);\n                }\n            });\n        });\n\n        // Handle network-level errors\n        req.on('error', (e) => {\n            resolve(`[Error executing query]: HTTPS Request failed - ${e.message}`);\n        });\n\n        req.write(postData);\n        req.end();\n    });\n}\n\n// Execute and return the formatted result to the flow state\nreturn await runSQLQuery(sqlQuery);",
