            {
              "variableName": "vendor_id",
              "variableValue": "<p><span class=\"variable\" data-type=\"mention\" data-id=\"question\" data-label=\"question\">{{ question }}</span>&nbsp;</p>"
            }
          ],
          "customFunctionJavascriptFunction": "const https = require('https');\n\nconst connectionString = \"postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require\";\n\nasync function fetchInvoiceData() {\n  return new Promise((resolve, reject) => {\n    try {\n      // Accept either invoice_id (INV...) or vendor_id (VEND...) from input\n      const rawInput = typeof $vendor_id !== 'undefined' ? String($vendor_id) : '';\n      \n      const invoiceMatch = rawInput.match(/INV\\w+/i);\n      const vendorMatch = rawInput.match(/VEND\\d+/i);\n\n      let query, params, lookupMode;\n\n      if (invoiceMatch) {\n        // Single invoice lookup - full JOIN to get all data needed by all 3 agents\n        lookupMode = 'invoice';\n        query = `\n          SELECT\n            i.invoice_id,\n            i.date            AS invoice_date,\n            i.vendor_id,\n            i.invoice_number,\n            i.po_id,\n            i.grn_id,\n            i.invoice_amount,\n            i.gstin            AS invoice_gstin,\n            po.po_amount,\n            po.status          AS approval_status,\n            po.po_date,\n            po.vendor_id       AS po_vendor_id,\n            gr.received_amount AS grn_amount,\n            gr.receipt_date,\n            vm.vendor_name,\n            vm.official_gstin  AS official_gstin,\n            vm.risk_rating     AS vendor_risk_rating,\n            vm.blacklist_status\n          FROM invoices i\n          LEFT JOIN purchase_orders po  ON i.po_id  = po.po_id\n          LEFT JOIN goods_receipts  gr  ON i.grn_id = gr.grn_id\n          LEFT JOIN vendor_master   vm  ON i.vendor_id = vm.vendor_id\n          WHERE i.invoice_id ILIKE $1\n          LIMIT 1;\n        `;\n        params = [invoiceMatch[0].toUpperCase()];\n      } else if (vendorMatch) {\n        // Vendor-level lookup - get all invoices for this vendor\n        lookupMode = 'vendor';\n        query = `\n          SELECT\n            i.invoice_id,\n            i.date            AS invoice_date,\n            i.vendor_id,\n            i.invoice_number,\n            i.po_id,\n            i.grn_id,\n            i.invoice_amount,\n            i.gstin            AS invoice_gstin,\n            po.po_amount,\n            po.status          AS approval_status,\n            po.po_date,\n            gr.received_amount AS grn_amount,\n            gr.receipt_date,\n            vm.vendor_name,\n            vm.official_gstin  AS official_gstin,\n            vm.risk_rating     AS vendor_risk_rating,\n            vm.blacklist_status\n          FROM invoices i\n          LEFT JOIN purchase_orders po  ON i.po_id  = po.po_id\n          LEFT JOIN goods_receipts  gr  ON i.grn_id = gr.grn_id\n          LEFT JOIN vendor_master   vm  ON i.vendor_id = vm.vendor_id\n          WHERE i.vendor_id ILIKE $1\n          ORDER BY i.date DESC\n          LIMIT 20;\n        `;\n        params = [vendorMatch[0].toUpperCase()];\n      } else {\n        return resolve(JSON.stringify({\n          error: \"Invalid input\",\n          details: \"Please provide an invoice ID (e.g., INV40001) or vendor ID (e.g., VEND1001).\",\n          raw_input: rawInput\n        }, null, 2));\n      }\n\n      const postData = JSON.stringify({ query, params });\n      const options = {\n        hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',\n        port: 443,\n        path: '/sql',\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n          'Neon-Connection-String': connectionString,\n          'Content-Length': Buffer.byteLength(postData)\n        }\n      };\n\n      const req = https.request(options, (res) => {\n        let body = '';\n        res.on('data', chunk => body += chunk);\n        res.on('end', () => {\n          if (res.statusCode >= 200 && res.statusCode < 300) {\n            try {\n              const parsed = JSON.parse(body);\n              const rows = parsed.rows || parsed;\n              \n              if (!rows || rows.length === 0) {\n                return resolve(JSON.stringify({\n                  error: `No records found`,\n                  lookup_mode: lookupMode,\n                  lookup_value: params[0]\n                }, null, 2));\n              }\n\n              // For single invoice, return the row directly with extra context\n              if (lookupMode === 'invoice') {\n                const row = rows[0];\n                // Add mismatch helpers for Phase 2A\n                const inv = parseFloat(row.invoice_amount) || 0;\n                const po  = parseFloat(row.po_amount) || 0;\n                const grn = parseFloat(row.grn_amount) || 0;\n                row._three_way_match_ok = (inv > 0 && po > 0 && grn > 0)\n                  ? (Math.abs(inv - po) / po < 0.01 && Math.abs(inv - grn) / grn < 0.01)\n                  : null;\n                row._requires_enhanced_approval = inv > 100000;\n                resolve(JSON.stringify(row, null, 2));\n              } else {\n                // For vendor, return all invoices as array\n                resolve(JSON.stringify({ vendor_id: params[0], invoice_count: rows.length, invoices: rows }, null, 2));\n              }\n            } catch (e) {\n              resolve(JSON.stringify({ error: \"JSON parse failed\", details: e.message }));\n            }\n          } else {\n            resolve(JSON.stringify({ error: `Neon HTTP Error ${res.statusCode}`, details: body }));\n          }\n        });\n      });\n\n      req.on('error', e => resolve(JSON.stringify({ error: \"Network error\", message: e.message })));\n      req.write(postData);\n      req.end();\n\n    } catch (err) {\n      resolve(JSON.stringify({ error: String(err), message: err.message }));\n    }\n  });\n}\n\nreturn await fetchInvoiceData();\n",
