          ],
          "customFunctionJavascriptFunction": "\ntry {\n    const parseFlags = (str) => {\n        try {\n            const match = String(str).match(/\\[.*\\]/s);\n            if (match) return JSON.parse(match[0]);\n            return [];\n        } catch(e) { return []; }\n    };\n    \n    let allFlags = [\n        ...parseFlags($flags_2a),\n        ...parseFlags($flags_2b),\n        ...parseFlags($flags_2c)\n    ];\n    \n    let highestSeverity = \"NONE\";\n    const severityRankParams = {\"CRITICAL\":4, \"HIGH\":3, \"MEDIUM\":2, \"LOW\":1, \"NONE\":0 };\n    \n    allFlags.forEach(f => {\n        let s = String(f.Severity || f.severity || \"LOW\").toUpperCase();\n        if (severityRankParams[s] > severityRankParams[highestSeverity]) {\n            highestSeverity = s;\n        }\n    });\n\n    let polVers = typeof $policy_version === \"string\" ? parseFloat($policy_version.replace(/[^0-9.]/g, '')) : 1.0;\n\n    let result = {\n        risk_rating: highestSeverity,\n        flags_detected: allFlags,\n        policy_version_applied: isNaN(polVers) ? 1.0 : polVers\n    };\n    \n    return JSON.stringify(result);\n} catch(err) {\n    return JSON.stringify({ risk_rating: \"ERROR\", flags_detected: [], policy_version_applied: 1.0 });\n}\n",
