                    "css": ":root {
  --bg-color: #f7f9fa;
  --card-bg: #ffffff;
  --text-main: #2A2A2A;
  --text-muted: #5e6c84;
  --border-color: #dfe1e6;
  --alert-red: #de350b;
  --accent-blue: #0052cc;
  --success-green: #00875a;
  --warning-orange: #ff991f;
  --vibrant-purple: #6554c0;
  --radius: 8px;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-color);
  padding: 24px;
  color: var(--text-main);
  margin: 0;
}

.genw-dashboard {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.row {
  display: grid;
  gap: 24px;
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

.grid-2 {
  grid-template-columns: 1fr 1fr;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.08);
}

h3 {
  margin: 0 0 20px 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

/* KPIs */
.kpi {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  border-top: 4px solid var(--accent-blue);
  padding: 20px;
}

.kpi.alert {
  border-top-color: var(--alert-red);
}

.kpi.warning {
  border-top-color: var(--warning-orange);
}

.kpi.purple {
  border-top-color: var(--vibrant-purple);
}

.kpi.success {
  border-top-color: var(--success-green);
}

.kpi p {
  font-size: 32px;
  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Rules */
.connector-grid {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.rule-card {
  background: #fafbfc;
  border: 1px solid var(--border-color);
  border-left: 4px solid var(--border-color);
  padding: 16px;
  border-radius: var(--radius);
  flex: 1;
  min-width: 180px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.2s, box-shadow 0.2s;
}

.rule-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.05);
}

.rule-card h4 {
  margin: 0;
  font-size: 14px;
  color: var(--text-main);
}

.rule-card p {
  margin: 0;
  font-size: 12px;
  color: var(--text-muted);
}

.rule-card .status-text {
  font-size: 11px;
  font-weight: 600;
  margin-top: auto;
}

.rule-card.active {
  border-left-color: var(--success-green);
}

.rule-card.active .status-text {
  color: var(--success-green);
}

.rule-card.warning {
  border-left-color: var(--warning-orange);
}

.rule-card.warning .status-text {
  color: var(--warning-orange);
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

th {
  border-bottom: 2px solid var(--border-color);
  padding: 12px 10px;
  color: var(--text-muted);
  font-weight: 600;
  text-align: left;
  background: #fafbfc;
}

td {
  border-bottom: 1px solid var(--border-color);
  padding: 14px 10px;
  color: var(--text-main);
  vertical-align: middle;
}

tr:hover td {
  background: #fcfcfd;
}

.risk-pill {
  padding: 4px 10px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 700;
  display: inline-block;
}

.risk-high {
  background: #ffebe6;
  color: var(--alert-red);
}

.risk-med {
  background: #fff0b3;
  color: var(--warning-orange);
}",
                    "js": "appsmith.onReady(() => {
  // We wrap the rendering logic in a function so we can call it 
  // both on load and whenever the database query finishes running.
  const renderDashboard = currentModel => {
    // 1. Extract dynamic data passed from the Default Model
    // Fallback to 0/empty arrays if the API is still loading
    const dbData = currentModel.engine || {
      kpis: {
        violationsBlocked: 0,
        highRiskFlags: 0,
        autoEscalated: 0
      },
      feed: []
    };

    // 2. Define Data Object (Blending dynamic DB data with Mocked SOP data)
    const engineData = {
      kpis: {
        rules: "10",
        violations: dbData.kpis.violationsBlocked.toLocaleString(),
        highRisk: dbData.kpis.highRiskFlags.toLocaleString(),
        escalated: dbData.kpis.autoEscalated.toLocaleString()
      },
      feed: dbData.feed.length > 0 ? dbData.feed : [{
        id: "---",
        rule: "Waiting for database...",
        entity: "---",
        risk: "---"
      }],
      // Mocked: Rule effectiveness scaled down to fit a ~50 invoice dataset
      effectiveness: [{
        rule: "Three-Way Match Verification",
        count: "12",
        valid: "83%"
      }, {
        rule: "Approval Hierarchy DOA",
        count: "5",
        valid: "100%"
      }, {
        rule: "Timing Anomalies (Weekend)",
        count: "8",
        valid: "87%"
      }, {
        rule: "Transaction Splitting",
        count: "3",
        valid: "66%"
      }]
    };

    // 3. Populate Top KPI Cards
    const kpiRules = document.getElementById('kpi-rules');
    const kpiViolations = document.getElementById('kpi-violations');
    const kpiHighRisk = document.getElementById('kpi-high-risk');
    const kpiEscalated = document.getElementById('kpi-escalated');
    if (kpiRules) kpiRules.textContent = engineData.kpis.rules;
    if (kpiViolations) kpiViolations.textContent = engineData.kpis.violations;
    if (kpiHighRisk) kpiHighRisk.textContent = engineData.kpis.highRisk;
    if (kpiEscalated) kpiEscalated.textContent = engineData.kpis.escalated;

    // 4. Populate Dynamic Violation Feed
    const feedBody = document.querySelector('#violation-table tbody');
    if (feedBody) {
      feedBody.innerHTML = "";
      engineData.feed.forEach(v => {
        let riskClass = v.risk === "CRITICAL" || v.risk === "HIGH" ? "risk-high" : "risk-med";
        let displayRule = v.rule.length > 30 ? v.rule.substring(0, 30) + '...' : v.rule;
        feedBody.innerHTML += `<tr>
          <td><strong>${v.id}</strong></td>
          <td>${displayRule}</td>
          <td>${v.entity}</td>
          <td><span class="risk-pill ${riskClass}">${v.risk || 'UNKNOWN'}</span></td>
        </tr>`;
      });
    }

    // 5. Populate Mocked Effectiveness Table
    const effBody = document.querySelector('#effectiveness-table tbody');
    if (effBody) {
      effBody.innerHTML = "";
      engineData.effectiveness.forEach(e => {
        effBody.innerHTML += `<tr>
          <td>${e.rule}</td>
          <td>${e.count}</td>
          <td><strong>${e.valid}</strong></td>
        </tr>`;
      });
    }
  };

  // Run the render function immediately when the widget mounts
  renderDashboard(appsmith.model);

  // Re-run the render function anytime Api1 fetches new data
  appsmith.onModelChange(newModel => {
    renderDashboard(newModel);
  });
});"
