                    "js": "const FLOWISE_API = "https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/8570af9e-7d76-408a-b755-6821649759e9";
appsmith.onReady(() => {
  renderQueue(appsmith.model.pendingRecords || appsmith.model.allRecords || []);
  appsmith.onModelChange(newModel => {
    renderQueue(newModel.pendingRecords || newModel.allRecords || []);
  });
});
function renderQueue(records) {
  const container = document.getElementById('queue-container');

  // 1. Calculate and Update KPIs
  let pendingCount = 0;
  let highRiskCount = 0;
  let approvedCount = 0;
  let rejectedCount = 0;
  const queueRecords = [];
  records.forEach(record => {
    const risk = record.risk_rating || '';
    const status = record.recommended_action || '';
    if (status === 'Pending') {
      pendingCount++;
      if (risk === 'HIGH' || risk === 'CRITICAL') highRiskCount++;
      queueRecords.push(record); // Only pending items go in the queue
    } else if (status === 'Approved/Overridden' || status === 'Approved' || status === 'AUTO_APPROVE') {
      approvedCount++;
    } else if (status === 'Rejected') {
      rejectedCount++;
    }
  });

  // Inject KPI counts directly into the HTML
  if (document.getElementById('kpi-pending')) document.getElementById('kpi-pending').innerText = pendingCount;
  if (document.getElementById('kpi-high-risk')) document.getElementById('kpi-high-risk').innerText = highRiskCount;
  if (document.getElementById('kpi-approved')) document.getElementById('kpi-approved').innerText = approvedCount;
  if (document.getElementById('kpi-rejected')) document.getElementById('kpi-rejected').innerText = rejectedCount;

  // 2. Render the Queue
  if (!queueRecords || queueRecords.length === 0) {
    if (container) container.innerHTML = "<div style='padding: 20px; text-align: center; color: #666;'>Escalation queue is clear.</div>";
    return;
  }
  let html = '';
  queueRecords.forEach(record => {
    let details = {};
    try {
      details = JSON.parse(record.explanation);
    } catch (e) {
      details = {
        riskResult: {},
        verifiedFlags: [],
        extractedData: {}
      };
    }
    const vendorName = details.extractedData?.vendor_name || details.extractedData?.['Vendor Name'] || details.extractedData?.VendorName || "Unknown Vendor";
    const riskRating = details.riskResult?.riskLevel || "HIGH";
    const score = details.riskResult?.riskScore || 0;

    // Additional extracted data for auditors
    const invoiceAmt = details.extractedData?.invoice_amount || 'N/A';
    const poAmt = details.extractedData?.po_amount || 'N/A';
    const invoiceGstin = details.extractedData?.invoice_gstin || 'N/A';
    const officialGstin = details.extractedData?.official_gstin || 'N/A';
    const invoiceDate = details.extractedData?.invoice_date || 'N/A';
    let flagsHtml = (details.verifiedFlags || []).map(f => {
      // Hardened against Flowise changing key cases
      const severity = f.Severity || f.severity || 'FLAG';
      const flagType = f['Flag Type'] || f.flag_type || 'Anomaly';
      const evidence = f.Evidence || f.evidence || '';
      return `
      <div class="flag-item">
        <strong>${severity}:</strong> ${flagType} <br/>
        <span style="font-size: 13px; color: #555;">${evidence}</span>
      </div>
    `;
    }).join('');
    html += `
      <div class="record-card" id="rec-${record.invoice_id}">
        <div class="record-header">
          <h4 style="margin:0; font-size: 16px; color: #333;">${record.invoice_id} | ${vendorName}</h4>
          <span style="background:${riskRating === 'CRITICAL' ? '#d32f2f' : '#ff9800'}; color:white; padding:4px 10px; border-radius:12px; font-weight:bold; font-size:12px;">
            Risk Score: ${score}/100
          </span>
        </div>

        <div class="record-details" style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-size: 13px; margin-bottom: 16px; color: #444;">
          <div><strong>Invoice Amount:</strong> $${invoiceAmt}</div>
          <div><strong>PO Amount:</strong> $${poAmt}</div>
          <div><strong>Inv GSTIN:</strong> ${invoiceGstin}</div>
          <div><strong>Off. GSTIN:</strong> ${officialGstin}</div>
          <div><strong>Invoice Date:</strong> ${invoiceDate}</div>
        </div>

        <div style="margin-bottom:16px;">
          ${flagsHtml || '<span style="color:#888; font-size: 13px;">No specific flags extracted.</span>'}
        </div>
        <div class="action-bar" style="display: flex; gap: 10px;">
          <button class="btn-approve" onclick="handleAction('${record.invoice_id}', '${record.session_id}', 'proceed', 'Approved/Overridden')">Approve / Override Flag</button>
          <button class="btn-reject" onclick="handleAction('${record.invoice_id}', '${record.session_id}', 'hard-reject', 'Rejected')">Reject</button>
          <button class="btn-override" onclick="handleAction('${record.invoice_id}', '${record.session_id}', 'edge-human-rejected-to-loop', 'Re-analyzing')">Re-analyze</button>
        </div>
      </div>
    `;
  });
  if (container) container.innerHTML = html;
}
window.handleAction = async function (invoiceId, sessionId, flowiseAction, finalStatus) {
  let userFeedback = "Rejected by auditor.";
  if (flowiseAction !== 'hard-reject') {
    userFeedback = prompt(`Please enter your justification/feedback for ${finalStatus}:`);
    if (userFeedback === null) return;
  }
  const card = document.getElementById('rec-' + invoiceId);
  if (card) {
    card.style.opacity = '0.5';
    card.querySelector('.action-bar').innerHTML = "<span style='color: #666; font-weight: bold;'>Processing... Please wait.</span>";
  }
  try {
    let finalPack = null;
    if (flowiseAction !== 'hard-reject') {
      const response = await fetch(FLOWISE_API, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          chatId: sessionId,
          action: flowiseAction,
          question: userFeedback
        })
      });
      const resultData = await response.json();
      finalPack = resultData.text;
    }

    // Trigger the query with the properly formatted payload
    appsmith.triggerEvent('onAction', {
      invoiceId: invoiceId,
      status: finalStatus,
      finalPack: finalPack
    });
  } catch (error) {
    console.error("Error resuming flow:", error);
    alert("Failed to process action.");
    if (card) card.style.opacity = '1';
  }
