  --bg-color: #f7f9fa;
  --card-bg: #ffffff;
  --text-main: #2A2A2A;
  --text-muted: #5e6c84;
  --border-color: #dfe1e6;
  --alert-red: #de350b;
  --accent-blue: #0052cc;
  --success-green: #00875a;
  --warning-orange: #ff991f;
  --vibrant-purple: #6554c0;
  --radius: 8px;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-color);
  padding: 24px;
  color: var(--text-main);
  margin: 0;
}

.genw-dashboard {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.row {
  display: grid;
  gap: 24px;
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

.grid-2 {
  grid-template-columns: 1fr 1fr;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.08);
}

h3 {
  margin: 0 0 20px 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

/* KPIs */
.kpi {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  border-top: 4px solid var(--accent-blue);
  padding: 20px;
}

.kpi.success {
  border-top-color: var(--success-green);
}

.kpi.alert {
  border-top-color: var(--alert-red);
}

.kpi.purple {
  border-top-color: var(--vibrant-purple);
}

.kpi p {
  font-size: 32px;
  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Pipeline */
.pipeline-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
}

.pipe-node {
  flex: 1;
  border: 2px dashed var(--border-color);
  padding: 20px;
  text-align: center;
  border-radius: 6px;
  background: #fafbfc;
