        "body": "export default {
  getVendorIntelligenceData: async () => {
    // Hardcoding credentials locally for testing via Neon HTTP API
    const connectionString = "postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw-pooler.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";
    const neonHttpEndpoint = "https://ep-bitter-credit-a1ffz9vw-pooler.ap-southeast-1.aws.neon.tech/sql";

    try {
      // 1. Fetch real KPIs from the vendor_master table
      const kpiQuery = `
        SELECT 
          COUNT(*) as screened,
          COUNT(*) FILTER (WHERE blacklist_status = false AND (risk_rating ILIKE 'low' OR risk_rating IS NULL)) as verified,
          COUNT(*) FILTER (WHERE risk_rating ILIKE 'pending') as pending,
          COUNT(*) FILTER (WHERE blacklist_status = true OR risk_rating ILIKE 'high') as risk
        FROM vendor_master;
      `;

      const kpiResponse = await fetch(neonHttpEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Neon-Connection-String': connectionString },
        body: JSON.stringify({ query: kpiQuery, params: [] })
      });
      const kpiData = await kpiResponse.json();
      const kpis = (kpiData.rows && kpiData.rows.length > 0) ? kpiData.rows[0] : { screened: 0, verified: 0, pending: 0, risk: 0 };

      // 2. Fetch the actual vendor list
      const vendorQuery = `
        SELECT vendor_id, vendor_name, risk_rating, official_gstin, blacklist_status 
        FROM vendor_master 
        ORDER BY vendor_id DESC 
        LIMIT 10;
      `;

      const vendorResponse = await fetch(neonHttpEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Neon-Connection-String': connectionString },
        body: JSON.stringify({ query: vendorQuery, params: [] })
      });
      const vendorData = await vendorResponse.json();
      const vendors = vendorData.rows || [];

      // 3. Map the real data to the widget structure & mock the missing compliance fields
      const formattedCompanies = vendors.map(v => {

        // MOCK: Convert your text-based risk_rating to a visual XX/100 score
        let score = "Pending";
        let scoreClass = "score-pending";
        const rating = (v.risk_rating || '').toLowerCase();

        if (rating === 'low') { score = "98/100"; scoreClass = "score-good"; }
        else if (rating === 'medium') { score = "65/100"; scoreClass = "score-med"; }
        else if (rating === 'high') { score = "21/100"; scoreClass = "score-bad"; }

        // REAL: Evaluate real GSTIN and Blacklist statuses from your database
        const gstinStatus = v.official_gstin ? "Active" : "Mismatch";
        const gstinClass = v.official_gstin ? "pass" : "warn";

        const watchlistStatus = v.blacklist_status ? "Flagged" : "Clear";
        const watchlistClass = v.blacklist_status ? "fail" : "pass";

        return {
          id: v.vendor_id,
          name: v.vendor_name || "Unknown Vendor",
          score: score,
          scoreClass: scoreClass,
          flow: [
            // KYC and Bank Match are mocked since they aren't in the schema
            { name: "KYC Check", icon: "🏢", status: "Verified", statClass: "pass" },
            { name: "GSTIN Valid", icon: "📑", status: gstinStatus, statClass: gstinClass },
            { name: "Bank Match", icon: "🏦", status: "Matched", statClass: "pass" }, 
            { name: "Watchlist", icon: "🔍", status: watchlistStatus, statClass: watchlistClass }
          ]
        };
      });

      // 4. Return the exact JSON layout the custom widget expects
      return {
        kpis: {
          screened: Number(kpis.screened || 0).toLocaleString(),
          verified: Number(kpis.verified || 0).toLocaleString(),
          pending: Number(kpis.pending || 0).toLocaleString(),
          risk: Number(kpis.risk || 0).toLocaleString()
        },
        companies: formattedCompanies
      };

    } catch (err) {
      console.error("Failed to fetch from Neon DB:", err);
      // Fallback blank state if network fails
      return {
        kpis: { screened: "0", verified: "0", pending: "0", risk: "0" },
        companies: []
      };
    }
  }
}",
