        "body": "export default {
    agentResponse: {},
    currentSessionId: "", // Stores the ID to resume the flow later

    // 1. The initial query that pauses at the HITL node
    async fetchPrediction() {
        const userQuestion = Input1.text; 

        const response = await fetch(
            "https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/8570af9e-7d76-408a-b755-6821649759e9",
            {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    "question": userQuestion,
                    "overrideConfig": {
                        "modelName": "qwen3.5-35b-hacksplosion"
                    }
                })
            }
        );

        const result = await response.json();
        this.agentResponse = result;

        // Save the session/chat ID returned by the API so we can reply to it
        if (result.chatId || result.sessionId) {
            this.currentSessionId = result.chatId || result.sessionId;
        }

        return result;
    },

    // 2. The function triggered by your Accept/Reject buttons
    async resumeFlow(userDecision) {
        if (!this.currentSessionId) {
            return showAlert("No active session to review.", "error");
        }

        const response = await fetch(
            "https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/8570af9e-7d76-408a-b755-6821649759e9", 
            {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    // Send the decision (Approve or Re-analyze) as the input
                    "question": userDecision,
                    // Pass the saved ID to tell the API to resume the paused flow
                    "chatId": this.currentSessionId 
                })
            }
        );

        const result = await response.json();
        // Update the UI with the final "Generate Audit Pack" output
        this.agentResponse = result; 

        // Clear the session ID once complete
        this.currentSessionId = ""; 
        return result;
    }
