          "customFunctionJavascriptFunction": "const https = require('https');\n\n// Keep this secure or move to Key Store\nconst connectionString = \"postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require\";\n\n// Helper function to send HTTP requests to Neon\nasync function executeQuery(query, params = []) {\n    return new Promise((resolve, reject) => {\n        const postData = JSON.stringify({ query, params });\n        \n        const options = {\n            hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',\n            port: 443,\n            path: '/sql',\n            method: 'POST',\n            headers: {\n                'Content-Type': 'application/json',\n                'Neon-Connection-String': connectionString,\n                'Content-Length': Buffer.byteLength(postData)\n            }\n        };\n\n        const req = https.request(options, (res) => {\n            let data = '';\n            res.on('data', chunk => data += chunk);\n            res.on('end', () => {\n                if (res.statusCode >= 200 && res.statusCode < 300) {\n                    try {\n                        const parsed = JSON.parse(data);\n                        // Handle both array and object responses based on Neon API versions\n                        resolve(Array.isArray(parsed) ? parsed : parsed.rows || []);\n                    } catch (e) {\n                        reject(new Error(\"Failed to parse Neon JSON response\"));\n                    }\n                } else {\n                    reject(new Error(`Neon API Error: ${res.statusCode} - ${data}`));\n                }\n            });\n        });\n\n        req.on('error', reject);\n        req.write(postData);\n        req.end();\n    });\n}\n\nasync function getSQLPrompt() {\n    let sqlSchemaPrompt = '';\n    \n    try {\n        // 1. Get all user-defined tables\n        const tablesResult = await executeQuery(`\n            SELECT table_name \n            FROM information_schema.tables \n            WHERE table_schema = 'public' AND table_type = 'BASE TABLE'\n        `);\n        \n        for (const tableRow of tablesResult) {\n            const tableName = tableRow.table_name;\n            \n            // 2. Get column definitions for each table\n            const schemaInfo = await executeQuery(`\n                SELECT column_name, data_type, is_nullable \n                FROM information_schema.columns \n                WHERE table_name = $1\n            `, [tableName]);\n            \n            const createColumns = [];\n            const columnNames = [];\n            \n            for (const column of schemaInfo) {\n                const name = column.column_name;\n                const type = column.data_type.toUpperCase();\n                const notNull = column.is_nullable === 'NO' ? 'NOT NULL' : '';\n                columnNames.push(name);\n                createColumns.push(`${name} ${type} ${notNull}`.trim());\n            }\n            \n            const sqlCreateTableQuery = `CREATE TABLE ${tableName} (${createColumns.join(', ')});`;\n            const sqlSelectTableQuery = `SELECT * FROM ${tableName} LIMIT 3;`;\n            let allValues = [];\n            \n            // 3. Fetch sample rows to give the LLM data context\n            try {\n                const rows = await executeQuery(sqlSelectTableQuery);\n                allValues = rows.map(row => \n                    columnNames.map(col => {\n                        return row[col] === null ? 'NULL' : String(row[col]);\n                    }).join(' | ')\n                );\n            } catch (err) {\n                allValues.push('[ERROR FETCHING SAMPLE ROWS]');\n            }\n            \n            // Append formatted table schema to the final prompt\n            sqlSchemaPrompt += sqlCreateTableQuery + '\\n' + \n                               sqlSelectTableQuery + '\\n' + \n                               columnNames.join(' | ') + '\\n' + \n                               allValues.join('\\n') + '\\n\\n';\n        }\n        \n        return sqlSchemaPrompt;\n        \n    } catch (err) {\n        console.error(err);\n        return `Error generating schema: ${err.message}`;\n    }\n}\n\n// Execute and return the generated schema text to the flow state\nreturn await getSQLPrompt();",
