                    "js": "appsmith.onReady(() => {
  // We wrap the rendering logic in a function so we can call it 
  // both on load and whenever the database query finishes running.
  const renderDashboard = (currentModel) => {

    // 1. Extract dynamic data passed from the Default Model
    // Fallback to 0/empty arrays if the API is still loading
    const dbData = currentModel.engine || {
      kpis: { violationsBlocked: 0, highRiskFlags: 0, autoEscalated: 0 },
      feed: []
    };

    // 2. Define Data Object (Blending dynamic DB data with Mocked SOP data)
    const engineData = {
      kpis: {
        rules: "10", 
        violations: dbData.kpis.violationsBlocked.toLocaleString(),
        highRisk: dbData.kpis.highRiskFlags.toLocaleString(),
        escalated: dbData.kpis.autoEscalated.toLocaleString()
      },
      feed: dbData.feed.length > 0 ? dbData.feed : [
        { id: "---", rule: "Waiting for database...", entity: "---", risk: "---" }
      ],
      // Mocked: Rule effectiveness scaled down to fit a ~50 invoice dataset
      effectiveness: [
        { rule: "Three-Way Match Verification", count: "12", valid: "83%" },
        { rule: "Approval Hierarchy DOA", count: "5", valid: "100%" },
        { rule: "Timing Anomalies (Weekend)", count: "8", valid: "87%" },
        { rule: "Transaction Splitting", count: "3", valid: "66%" }
      ]
    };

    // 3. Populate Top KPI Cards
    const kpiRules = document.getElementById('kpi-rules');
    const kpiViolations = document.getElementById('kpi-violations');
    const kpiHighRisk = document.getElementById('kpi-high-risk');
    const kpiEscalated = document.getElementById('kpi-escalated');

    if (kpiRules) kpiRules.textContent = engineData.kpis.rules;
    if (kpiViolations) kpiViolations.textContent = engineData.kpis.violations;
    if (kpiHighRisk) kpiHighRisk.textContent = engineData.kpis.highRisk;
    if (kpiEscalated) kpiEscalated.textContent = engineData.kpis.escalated;

    // 4. Populate Dynamic Violation Feed
    const feedBody = document.querySelector('#violation-table tbody');
    if (feedBody) {
      feedBody.innerHTML = "";
      engineData.feed.forEach(v => {
        let riskClass = (v.risk === "CRITICAL" || v.risk === "HIGH") ? "risk-high" : "risk-med";
        let displayRule = v.rule.length > 30 ? v.rule.substring(0, 30) + '...' : v.rule;

        feedBody.innerHTML += `<tr>
          <td><strong>${v.id}</strong></td>
          <td>${displayRule}</td>
          <td>${v.entity}</td>
          <td><span class="risk-pill ${riskClass}">${v.risk || 'UNKNOWN'}</span></td>
        </tr>`;
      });
    }

    // 5. Populate Mocked Effectiveness Table
    const effBody = document.querySelector('#effectiveness-table tbody');
    if (effBody) {
      effBody.innerHTML = "";
      engineData.effectiveness.forEach(e => {
        effBody.innerHTML += `<tr>
          <td>${e.rule}</td>
          <td>${e.count}</td>
          <td><strong>${e.valid}</strong></td>
        </tr>`;
      });
    }
  };

  // Run the render function immediately when the widget mounts
  renderDashboard(appsmith.model);

  // Re-run the render function anytime Api1 fetches new data
  appsmith.onModelChange((newModel) => {
    renderDashboard(newModel);
  });
});"
