                    "js": "const assistantData = {
  initialMessage: "<strong>Audit Context Loaded: INV-9942</strong><br>I have analyzed the transaction. The invoice quantity (500 units) exceeds the Goods Receipt Note (450 units). Potential overbilling risk detected. How would you like to investigate?",
  suggestions: ["Summarize financial impact", "Show historical vendor anomalies", "Draft escalation email to VEND1011"],
  context: {
    recordHtml: `
      <span><strong>Entity:</strong> Global Tech Imports</span>
      <span><strong>Transaction ID:</strong> INV-9942</span>
      <span><strong>Linked PO:</strong> PO-4412</span>
      <span><strong>Risk Score:</strong> 98/100</span>
      <span class="status-pill status-high">Critical Flag</span>
    `,
    evidenceLinks: ["📄 <a href='#'>Source_Invoice_9942.pdf (Page 1)</a>", "📦 <a href='#'>Warehouse_GRN_4412.xml</a>", " Policy: <a href='#'>Sec 4.1 - Three-Way Matching</a>", "📊 Logs: <a href='#'>Vendor_History_Report.csv</a>"]
  }
};
const history = document.getElementById('chat-history');
const suggestionsBox = document.getElementById('chat-suggestions');
const inputField = document.getElementById('chat-input');

// Render Initial State
function initAssistant() {
  // Context
  document.getElementById('active-record').innerHTML = assistantData.context.recordHtml;
  const evList = document.getElementById('evidence-list');
  assistantData.context.evidenceLinks.forEach(link => {
    evList.innerHTML += `<li>${link}</li>`;
  });

  // Bot Message
  appendMessage('bot', assistantData.initialMessage);

  // Suggestions
  assistantData.suggestions.forEach(s => {
    suggestionsBox.innerHTML += `<button class="pill-suggestion" onclick="fillInput('${s}')">${s}</button>`;
  });
}
function appendMessage(sender, text) {
  const msgDiv = document.createElement('div');
  msgDiv.className = `msg msg-${sender}`;
  msgDiv.innerHTML = text;
  history.appendChild(msgDiv);
  history.scrollTop = history.scrollHeight;
}

// Updated: Autofills the chat input instead of auto-sending
function fillInput(text) {
  // Hide the suggestions box to clear up screen space
  if (suggestionsBox) {
    suggestionsBox.style.display = "none";
  }

  // Autofill the input field
  inputField.value = text;

  // Automatically put the cursor in the input field so you can just hit Enter
  inputField.focus();
}

// Added: Simple Markdown to HTML parser for LLM formatting
function parseMarkdown(text) {
  if (!text) return "";
  return text.replace(/^### (.*$)/gim, '<h3>$1</h3>').replace(/^## (.*$)/gim, '<h2>$1</h2>').replace(/^# (.*$)/gim, '<h1>$1</h1>').replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>').replace(/\*(.*)\*/gim, '<em>$1</em>').replace(/`(.*?)`/gim, '<code style="background:#eee; padding:2px 4px; border-radius:3px;">$1</code>').replace(/\n/gim, '<br>');
}
async function sendMessage(text) {
  if (!text) return;

  // 1. Append user message to the UI
  history.innerHTML += `<div class="user-msg"><b>You:</b> ${text}</div>`;
  inputField.value = ''; // Clear input

  // Optional: Add a temporary loading indicator
  const loadingId = 'loading-' + Date.now();
  history.innerHTML += `<div id="${loadingId}" class="ai-msg"><b>Assistant:</b> <i>Thinking...</i></div>`;
  history.scrollTop = history.scrollHeight;
  try {
    // 2. Make the direct HTTP request to Agent Builder
    const response = await fetch('https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/a70f8f8e-a621-47a6-a7c9-20dd347bf0e5', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        question: text
      }) // Sending just the typed question
    });
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data = await response.json();

    // 3. Remove loading indicator
    document.getElementById(loadingId).remove();

    // Parse the response
    const replyText = data.text || data.answer || JSON.stringify(data);

    // Apply Markdown Parsing
    const formattedReply = parseMarkdown(replyText);

    // 4. Append the formatted AI's response to the UI
    history.innerHTML += `<div class="ai-msg"><b>Assistant:</b><br>${formattedReply}</div>`;
    history.scrollTop = history.scrollHeight;
  } catch (error) {
    // Handle CORS or network errors gracefully in the UI
    document.getElementById(loadingId).remove();
    history.innerHTML += `<div style="color: red; font-size: 0.8em; margin-top: 5px;"><b>System Error:</b> Could not reach AI (${error.message}). Check console for CORS issues.</div>`;
    history.scrollTop = history.scrollHeight;
  }
}

// Fixed: Combined duplicate Enter key listeners into a single clean listener
inputField.addEventListener("keypress", function (event) {
  if (event.key === "Enter") {
    event.preventDefault();
    sendMessage(inputField.value);
  }
});

// Initializing the component 
// Initializing the component safely
appsmith.onReady(() => {
  initAssistant();
});
// Attaching fillInput to the global window object explicitly to prevent ReferenceErrors from inline HTML onclicks inside iframes
window.fillInput = fillInput;"
