}

.context-details strong {
  color: var(--text-muted);
}

.evidence-list {
  list-style: none;
  padding: 0;
  margin: 16px 0 0 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.evidence-list li {
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.evidence-list a {
  color: var(--accent-blue);
  text-decoration: none;
  font-weight: 500;
}

.evidence-list a:hover {
  text-decoration: underline;
}

.status-pill {
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
  display: inline-block;
  width: fit-content;
  margin-top: 4px;
}

.status-high {
  background: #ffebe6;
  color: var(--alert-red);
