    const vendors = vendorData.rows || [];
    const formattedCompanies = vendors.map(v => {
      let score = "Pending";
      let scoreClass = "score-pending";
      const rating = (v.risk_rating || '').toLowerCase();
      if (rating === 'low') {
        score = "98/100";
        scoreClass = "score-good";
      } else if (rating === 'medium') {
        score = "65/100";
        scoreClass = "score-med";
      } else if (rating === 'high') {
        score = "21/100";
        scoreClass = "score-bad";
      }
      const gstinStatus = v.official_gstin ? "Active" : "Mismatch";
      const gstinClass = v.official_gstin ? "pass" : "warn";
      const watchlistStatus = v.blacklist_status ? "Flagged" : "Clear";
      const watchlistClass = v.blacklist_status ? "fail" : "pass";
      return {
        id: v.vendor_id,
        name: v.vendor_name || "Unknown Vendor",
        score: score,
        scoreClass: scoreClass,
        flow: [{
          name: "KYC Check",
          icon: "🏢",
          status: "Verified",
          statClass: "pass"
        }, {
          name: "GSTIN Valid",
          icon: "📑",
          status: gstinStatus,
          statClass: gstinClass
        }, {
          name: "Bank Match",
          icon: "🏦",
          status: "Matched",
          statClass: "pass"
        }, {
          name: "Watchlist",
          icon: "🔍",
          status: watchlistStatus,
          statClass: watchlistClass
        }]
      };
    });
    return {
      kpis: {
        screened: Number(kpis.screened || 0).toLocaleString(),
        verified: Number(kpis.verified || 0).toLocaleString(),
        pending: Number(kpis.pending || 0).toLocaleString(),
        risk: Number(kpis.risk || 0).toLocaleString()
      },
      companies: formattedCompanies
    };
  } catch (err) {
    console.error("Failed to fetch from Neon DB:", err);
    return {
      kpis: {
        screened: "0",
        verified: "0",
        pending: "0",
        risk: "0"
      },
      companies: []
    };
  }
