        "inputs": {
          "customFunctionInputVariables": [],
          "customFunctionJavascriptFunction": "const https = require('https');\n\nconst connectionString = \"postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require\";\n\nasync function fetchPolicy() {\n  return new Promise((resolve) => {\n    const postData = JSON.stringify({\n      query: \"SELECT policy_id, markdown_content, version_number FROM company_policies WHERE is_active = true ORDER BY version_number DESC LIMIT 1;\"\n    });\n\n    const options = {\n      hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',\n      port: 443, path: '/sql', method: 'POST',\n      headers: {\n        'Content-Type': 'application/json',\n        'Neon-Connection-String': connectionString,\n        'Content-Length': Buffer.byteLength(postData)\n      }\n    };\n\n    const req = https.request(options, (res) => {\n      let body = '';\n      res.on('data', c => body += c);\n      res.on('end', () => {\n        try {\n          const parsed = JSON.parse(body);\n          const rows = parsed.rows || parsed;\n          if (rows && rows.length > 0) {\n            const policy = rows[0];\n            // Return both markdown and version as a combined JSON\n            resolve(JSON.stringify({\n              policy_markdown: policy.markdown_content,\n              policy_version: policy.version_number,\n              policy_id: policy.policy_id\n            }, null, 2));\n          } else {\n            resolve(JSON.stringify({ policy_markdown: \"No active policy found.\", policy_version: \"N/A\" }));\n          }\n        } catch(e) {\n          resolve(JSON.stringify({ policy_markdown: \"Policy fetch failed: \" + e.message, policy_version: \"N/A\" }));\n        }\n      });\n    });\n\n    req.on('error', e => resolve(JSON.stringify({ policy_markdown: \"Network error: \" + e.message, policy_version: \"N/A\" })));\n    req.write(postData);\n    req.end();\n  });\n}\n\nconst result = JSON.parse(await fetchPolicy());\n// Store both keys separately so agents can use them as flow state variables\nreturn JSON.stringify(result);\n",
