        "inputAnchors": [],
        "inputs": {
          "customFunctionInputVariables": [
            {
              "variableName": "verifiedFlags",
              "variableValue": "{{ $flow.state.verifiedFlags }}"
            }
          ],
          "customFunctionJavascriptFunction": "/*\n * Risk Scoring Calculator\n * Deterministic weighted formula for audit risk scoring\n * Weights: CRITICAL=30, HIGH=20, MEDIUM=10, LOW=5\n * Threshold: >= 70 requires human review\n */\n\nconst weights = { critical: 30, high: 20, medium: 10, low: 5 };\nlet counts = { critical: 0, high: 0, medium: 0, low: 0 };\n\ntry {\n    // Try to parse the verified flags from the previous phase\n    const text = $verifiedFlags || '';\n    \n    // Try JSON parse first\n    let parsed;\n    try {\n        // Find JSON in the text\n        const jsonMatch = text.match(/\\{[\\s\\S]*\\}/);\n        if (jsonMatch) {\n            parsed = JSON.parse(jsonMatch[0]);\n        }\n    } catch(e) {\n        parsed = null;\n    }\n    \n    if (parsed && parsed.summary) {\n        // Use the summary counts from the verifier\n        counts.critical = parsed.summary.critical || 0;\n        counts.high = parsed.summary.high || 0;\n        counts.medium = parsed.summary.medium || 0;\n        counts.low = parsed.summary.low || 0;\n    } else if (parsed && parsed.verifiedFlags && Array.isArray(parsed.verifiedFlags)) {\n        // Count from array of flags\n        for (const flag of parsed.verifiedFlags) {\n            const sev = (flag.severity || flag.Severity || 'medium').toLowerCase();\n            if (counts.hasOwnProperty(sev)) counts[sev]++;\n        }\n    } else {\n        // Fallback: count severity keywords in text\n        counts.critical = (text.match(/\\bcritical\\b/gi) || []).length;\n        counts.high = (text.match(/\\bhigh\\b/gi) || []).length;\n        counts.medium = (text.match(/\\bmedium\\b/gi) || []).length;\n        counts.low = (text.match(/\\blow\\b/gi) || []).length;\n        // Avoid over-counting by capping\n        counts.critical = Math.min(counts.critical, 10);\n        counts.high = Math.min(counts.high, 10);\n        counts.medium = Math.min(counts.medium, 10);\n        counts.low = Math.min(counts.low, 10);\n    }\n} catch(e) {\n    // If everything fails, default to medium risk\n    counts.medium = 3;\n}\n\n// Calculate weighted score\nlet score = counts.critical * weights.critical +\n            counts.high * weights.high +\n            counts.medium * weights.medium +\n            counts.low * weights.low;\n\n// Cap at 100\nscore = Math.min(score, 100);\n\n// Determine risk level\nlet level;\nif (score >= 70) level = 'CRITICAL';\nelse if (score >= 50) level = 'HIGH';\nelse if (score >= 30) level = 'MEDIUM';\nelse level = 'LOW';\n\nconst result = {\n    riskScore: score,\n    riskLevel: level,\n    breakdown: counts,\n    weights: weights,\n    threshold: 70,\n    requiresHumanReview: score >= 70,\n    routing: score >= 70 ? 'ESCALATE_TO_HUMAN' : 'AUTO_APPROVE'\n};\n\nreturn JSON.stringify(result, null, 2);",
