  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Connectors */
.connector-grid {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-connector {
  background: #fafbfc;
  border: 1px dashed var(--border-color);
  padding: 16px;
  border-radius: 6px;
  flex: 1;
  min-width: 180px;
  display: flex;
  flex-direction: column;
  gap: 12px;
