  flex-direction: column;
  gap: 4px;
}

.conn-text span {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-muted);
}

.btn-browse {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  padding: 6px 12px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-main);
  align-self: flex-start;
  transition: background 0.2s;
}

.btn-browse:hover {
  background: var(--bg-color);
}

.btn-connector.active {
  border-style: solid;
