async function processIngestionFlow(parsedRecords) {
    try {
        // STEP 1: Stage the parsed records in the widget model
        appsmith.updateModel({ pendingInvoices: parsedRecords });

        // STEP 2: Trigger the GenW event to insert records into Neon
        // In the GenW UI, configure 'onDbInsert' to run your bulk SQL insert query.
        // Your GenW query will read: {{CustomWidget1.model.pendingInvoices}}
        appsmith.triggerEvent("onDbInsert");

        // Note: Appsmith events are asynchronous. Assuming the insert is fast, 
        // we can immediately begin the agentic processing in the background.

        // STEP 3: Run Agent Builder for all invoices concurrently
        const agentPromises = parsedRecords.map(record => executeAgentFlow(record));

        // Promise.all ensures we wait for EVERY invoice to be processed
        const rawAgentResults = await Promise.all(agentPromises);

        // Filter out any agents that might have failed due to network errors
        const successfulAudits = rawAgentResults.filter(result => result !== null);

        // STEP 4: Stage the finalized audit results in the model
        appsmith.updateModel({ auditResults: successfulAudits });

        // STEP 5: Trigger the event to save these results to the audit_results table
        // In the GenW UI, configure 'onAuditSave' to run your insert query.
        // Your GenW query will read: {{CustomWidget1.model.auditResults}}
        appsmith.triggerEvent("onAuditSave");

        console.log("Entire ingestion and audit pipeline complete!");

    } catch (error) {
        console.error("Pipeline failed:", error);
    }
}

// The parallelized worker function
async function executeAgentFlow(invoiceRecord) {
    const API_URL = "https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/8570af9e-7d76-408a-b755-6821649759e9";

    // Construct the payload to trigger the specific Qwen3.5 multi-agent flow
    const payload = {
        question: `Audit transaction ${invoiceRecord.invoice_id} for vendor ${invoiceRecord.vendor_id}. Data: ${JSON.stringify(invoiceRecord)}`
    };

    try {
        const response = await fetch(API_URL, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });

        const output = await response.json();

        // Parse the agent's output to match your 'audit_results' database schema
        return {
            invoice_id: invoiceRecord.invoice_id,
            risk_rating: extractRisk(output.text), // e.g., "HIGH", "LOW"
            flags_detected: extractFlags(output.text), // Parse into JSONB array
            explanation: output.text,
            recommended_action: extractRecommendation(output.text),
            session_id: output.sessionId || null
        };
    } catch (error) {
        console.error(`Agent failed for invoice ${invoiceRecord.invoice_id}:`, error);
        return null; 
    }
}

// Helper parsing functions (customize based on your agent's exact JSON/text output)
function extractRisk(text) {
    if (text.includes("HIGH")) return "HIGH";
    if (text.includes("MEDIUM")) return "MEDIUM";
    return "LOW";
}

function extractFlags(text) {
    return []; // Replace with actual parsing logic to generate the jsonb array
}

function extractRecommendation(text) {
    return text.includes("AUTO_APPROVE") ? "AUTO_APPROVE" : "ESCALATE_TO_HUMAN";
