body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: var(--bg-color); padding: 24px; color: var(--text-main); margin: 0; }
.genw-dashboard { display: flex; flex-direction: column; gap: 24px; }
.row { display: grid; gap: 24px; }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

.card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow); transition: transform 0.2s, box-shadow 0.2s; }
.card:hover { box-shadow: 0 6px 12px rgba(0,0,0,0.08); }
h3 { margin: 0 0 20px 0; font-size: 13px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.8px; }

/* KPIs */
.kpi { display: flex; flex-direction: column; justify-content: center; text-align: center; border-top: 4px solid var(--accent-blue); padding: 20px; }
.kpi.alert { border-top-color: var(--alert-red); }
.kpi.warning { border-top-color: var(--warning-orange); }
.kpi.success { border-top-color: var(--success-green); }
.kpi p { font-size: 32px; font-weight: 800; margin: 0; color: var(--text-main); }

/* Connectors */
.connector-grid { display: flex; gap: 16px; flex-wrap: wrap; }
.btn-connector { background: #fafbfc; border: 1px dashed var(--border-color); padding: 16px; border-radius: 6px; flex: 1; min-width: 180px; display: flex; flex-direction: column; gap: 12px; transition: all 0.2s; }
.btn-connector.pending:hover { border-color: var(--accent-blue); }
.conn-text { font-weight: 600; color: var(--text-main); display: flex; flex-direction: column; gap: 4px; }
.conn-text span { font-size: 12px; font-weight: 400; color: var(--text-muted); }
.btn-browse { background: var(--card-bg); border: 1px solid var(--border-color); padding: 6px 12px; border-radius: 4px; cursor: pointer; font-size: 12px; font-weight: 500; color: var(--text-main); align-self: flex-start; transition: background 0.2s; }
.btn-browse:hover { background: var(--bg-color); }
.btn-connector.active { border-style: solid; border-color: var(--success-green); background: #e3fcef; }
.btn-connector.active .conn-text span { color: var(--success-green); }
.btn-connector.active .btn-browse { display: none; }

/* Tables */
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th { border-bottom: 2px solid var(--border-color); padding: 12px 10px; color: var(--text-muted); font-weight: 600; text-align: left; background: #fafbfc; }
td { border-bottom: 1px solid var(--border-color); padding: 14px 10px; color: var(--text-main); vertical-align: middle; }
tr:hover td { background: #fcfcfd; }
.status-pill { padding: 4px 10px; border-radius: 12px; font-size: 11px; font-weight: 700; display: inline-block; }
.status-complete { background: #e3fcef; color: var(--success-green); }
.status-processing { background: #deebff; color: var(--accent-blue); }
.status-failed { background: #ffebe6; color: var(--alert-red); }",
